/* @lc app=leetcode id=3841 lang=kotlin */ class Solution { fun ad(t: IntArray, i0: Int, v: Int) = generateSequence(i0) { it + (it and -it) }.takeWhile { it < t.size }.forEach { t[it] = t[it] xor v } fun qx(t: IntArray, i0: Int): Int = generateSequence(i0) { it - (it and -it) }.takeWhile { it > 0 }.fold(0) { a, i -> a xor t[i] } fun lca(up: Array<IntArray>, dep: IntArray, a0: Int, b0: Int): Int = (if (dep[a0] >= dep[b0]) a0 to b0 else b0 to a0).let { (a, b) -> (0 until 17).fold(a) { x, k -> if ((dep[a] - dep[b]) shr k and 1 == 1) up[k][x] else x }.let { a1 -> if (a1 == b) a1 else (16 downTo 0).fold(a1 to b) { (x, y), k -> if (up[k][x] != up[k][y]) up[k][x] to up[k][y] else x to y }.let { (x, _) -> up[0][x] } } } fun palindromePath(n: Int, edges: Array<IntArray>, s: String, queries: Array<String>): List<Boolean> = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> s.toCharArray().let { cs -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> IntArray(n).let { dep -> IntArray(n).let { tin -> IntArray(n).let { tout -> IntArray(n).let { base -> IntArray(1).let { ct -> java.util.ArrayDeque<Int>().also { it.addFirst(0) }.let { st -> generateSequence { st.pollFirst() }.forEach { e -> if (e >= 0) ct.set(0, ct[0] + 1).also { tin[e] = ct[0] }.also { base[e] = (if (e == 0) 0 else base[par[e]]) xor (1 shl (cs[e] - 'a')) }.also { dep[e] = if (e == 0) 0 else dep[par[e]] + 1 }.also { st.addFirst(e.inv()) }.also { g[e].orEmpty().filter { par[it] == -1 }.forEach { c -> par.set(c, e).also { st.addFirst(c) } } } else tout.set(e.inv(), ct[0]) }.let { Array(17) { IntArray(n) }.also { up -> par.copyInto(up[0]) }.also { up -> (1 until 17).forEach { k -> (0 until n).forEach { v -> up[k][v] = up[k - 1][up[k - 1][v]] } } }.let { up -> IntArray(n + 3).let { bit -> queries.mapNotNull { q -> q.split(" ").let { p -> if (p[0] == "update") p[1].toInt().let { w -> (1 shl (cs[w] - 'a')).let { o -> (1 shl (p[2][0] - 'a')).let { nw -> ad(bit, tin[w], o xor nw).also { ad(bit, tout[w] + 1, o xor nw) }.also { cs[w] = p[2][0] }.let { null } } } } else p[1].toInt().let { u -> p[2].toInt().let { v -> lca(up, dep, u, v).let { l -> (base[u] xor qx(bit, tin[u]) xor base[v] xor qx(bit, tin[v]) xor (1 shl (cs[l] - 'a'))).let { Integer.bitCount(it) <= 1 } } } } } } } } } } } } } } } } } } }